steps.command:
printf 'import yaml
yaml.warnings({"YAMLLoadWarning": True})
# CME-1321: Override yaml.load to require explicit Loader argument
_original_load = yaml.load
def _safe_load_wrapper(data, Loader=None):
    if Loader is None:
        raise TypeError("yaml.load() requires an explicit Loader argument. Use yaml.safe_load() or pass Loader=yaml.SafeLoader for untrusted data.")
    return _original_load(data, Loader=Loader)
yaml.load = _safe_load_wrapper
' > "$SITE_DIR/cme_1321_yaml_safe.pth"
